                    ((ota.progress * 100L) / ota.total).coerceIn(0L, 100L) else null
                val label = when (ota.state) {
                    0L -> "空闲"
                    1L -> "已排队"
                    2L -> "升级中"
                    3L -> when {
                        ota.phase == 7L -> "已回滚，请核对当前版本"
                        ota.phase == 8L || ota.result != 0 -> "升级失败，设备未确认安装成功"
